# Canvas: domain_adaptation_entities_v1
# Path: app/features/domain_adaptation/domain/entities.py

import uuid
from typing import List
from datetime import datetime, timezone
from pydantic import BaseModel, Field, ConfigDict


class AudioSample(BaseModel):
    """Represents a specific time-sliced audio preview for the Scout."""
    start_sec: float
    end_sec: float
    file_path: str = Field(description="The path to the temporary sliced audio file.")

    model_config = ConfigDict(frozen=True)


class ScoutResult(BaseModel):
    """The aggregated raw text preview generated by the CPU Whisper model."""
    source_id: uuid.UUID
    samples: List[AudioSample]
    combined_text: str = Field(description="The concatenated text from all audio samples.")

    model_config = ConfigDict(frozen=True)


class DomainGlossary(BaseModel):
    """
    The final, validated domain context.
    This is what gets injected as hotwords into the heavy GPU Whisper model.
    """
    id: uuid.UUID = Field(default_factory=uuid.uuid4)
    source_id: uuid.UUID
    industry: str = Field(description="The overarching industry from the appliance manifest.")
    sub_domain: str = Field(description="The specific sub-domain guessed by the classifier.")
    hotword_string: str = Field(description="The weighted hotwords formatted for Faster-Whisper (e.g., 'EBITDA:15.0').")

    created_at: datetime = Field(default_factory=lambda: datetime.now(timezone.utc))

    model_config = ConfigDict(from_attributes=True)